@Component
public class OrderSagaOrchestrator {

    private final KafkaTemplate<String, Object> kafkaTemplate;

    public OrderSagaOrchestrator(KafkaTemplate<String, Object> kafkaTemplate) {
        this.kafkaTemplate = kafkaTemplate;
    }

    public void startOrder(OrderCreatedEvent event) {
        try {
            // Dispatch command to Payment Service
            kafkaTemplate.send("payment-commands", new ProcessPaymentCommand(event.getOrderId(), event.getAmount()));
        } catch (Exception e) {
            // Initiate compensation workflow
            rollbackOrder(event.getOrderId());
        }
    }

    private void rollbackOrder(String orderId) {
        kafkaTemplate.send("order-events", new OrderCancelledEvent(orderId));
    }
}
